                    var pInvoiceID = CStr2(pParams.InvoiceID) == '' ? sessionStorage.CartOrderID : pParams.InvoiceID;

                    pDT = SalesPayment_offline().GetSalesReps(pInvoiceID);

                    $('#lstSalesPaymentSalesRep').empty();
                    for (var pIndex = 0; pIndex <= pDT.Rows.length - 1; pIndex++) {
                        pDR = pDT.Rows[pIndex];
                        if (pHtml != '')
                            pHtml += '<br />';
                        pHtml += HtmlEncode(pDR.PeopleName);

                        $('#lstSalesPaymentSalesRep').append($('<a data-role="none" class="list-group-item">')
                                    .append($('<table style="width:100%;">')
                                        .append($('<tr>')
                                            .append($('<td style="word-break:break-all;">').text(pDR.PeopleName))
                                            .append($('<td style="width:50px; text-align:center;">').append($('<span class="btn btn-xs btn-danger">')
                                                    .append($('<span class="bi-trash-fill" aria-hidden="true">'))
                                                    .data('data', pDR)
                                                    .click(function (e) {
                                                        e.preventDefault();
                                                        Business.TransInvoice.RemoveSalesRep({ PeopleID: $(this).data('data').PeopleID, InvoiceID: sessionStorage.CartOrderID });
                                                        proj.ShowSalesReps();
                                                    })
                                                ))
                                        )
                                    ))
                    }
                    //$('#divSalesPaymentSalesRepList').html(pHtml);

