                $('#txtAddChargePercent').change(function (e) {
                    var chargeAmount = CDec2($.trim($(this).val())) / 100;
                    //longChargeAmount = chargeAmount * CDec2(lblVATableSales);
                    var pSubTotal;
                    if (isSeniorCitizenPWDDiscount) {
                        pSubTotal = CDec2(SubTotalOfVatExemptItems) / (1 + (CDec2(taxPercent) / 100)) - seniorCitizenDiscount;
                        longChargeAmount = chargeAmount * pSubTotal;
                    } else {
                        // pSubTotal = CDec2($('#lblSalesPaySubTotal').text()); // old code
                        pSubTotal = CDec2($('#lblSalesPayAmountDue').text());
                        if (GetServiceChargeBasis() == 'vatin')
                            longChargeAmount = chargeAmount * pSubTotal;
                        else
                            longChargeAmount = chargeAmount * pSubTotal / (1 + (CDec2(taxPercent) / 100));
                    }

                    $('#txtAddCharge').val(longChargeAmount);
                });

