                function InitOtherPaymentFunctions() {
                    if (isInitOtherPaymentFx) { // to avoid double click
                        return;
                    }

                    $('#btnBackOtherPaymentType').unbind('click').click(function (e) {
                        e.preventDefault();
                        window.pageHeader.ShowPaymentsPage(false);
                    });

                    $('#selOtherPaymentType').unbind('change').change(function () {
                        var val = $('#selOtherPaymentType').val();
                        $('#txtSalesPayOtherPaymentTypeRoomNo').val('');
                        $('#divForVSED').show();
                        $('[name=spanRequiredForComplimentary]').show();
                        $('#divForRoomIn, #divForRoomInSendBill, #divForGCash, #vouchervalidation').hide();
                        $('#txtSalesPayOtherPaymentTypeIssuingOrg').val(sessionStorage.OrgName);
                        if (val == 'V-Plus') {
                            GetVPlusPoints();
                            $('#txtSalesPayOtherPaymentTypeRemarks').val('');
                        } else if (val == "Room In") {
                            $('#divForVSED, #divForGCash').hide();
                            $('#divForRoomIn, #divForRoomInSendBill').show();
                            //} else if (val == "Send Bill") {
                            //    $('#divForVSED, #divForRoomIn, #divForGCash').hide();
                            //    $('#divForRoomInSendBill').show();
                            //} else if (val == "GCash" || val == "GrabFood" || val == "FoodPanda") {
                            //    $('#divForVSED, #divForRoomIn, #divForRoomInSendBill').hide();

                            //    if (val == "GrabFood" || val == "FoodPanda") {
                            //        $('#dvGcashReferenceNo').css('visibility', 'hidden');
                            //        $('#dvGcashReferenceNo').css('display', 'none');
                            //    } else {
                            //        $('#dvGcashReferenceNo').css('visibility', 'visible');
                            //        $('#dvGcashReferenceNo').css('display', 'block');
                            //    }

                            //    $('#divForGCash').show();
                            //} else if (val == "Complimentary") {
                            //    $('[name=spanRequiredForComplimentary]').hide();
                        } else if (val == 'SupercardVoucher') {
                            $('#vouchervalidation').empty().show();
                        }

                        var opt = $('#selOtherPaymentType').find('option:selected');
                        var OPDataType = opt.attr('datatype');
                        var charlength = CInt2(opt.attr('charlength'));

                        if (CBool(opt.attr('strict'))) {
                            
                            $('#lblRefNoCharLength').html('<i>(Enter the <b>' + charlength + '-' + OPDataType + '</b> reference code, including the special characters like -,+.)</i>')
                            $('#txtSalesPayOtherPaymentTypeCardNo').attr('maxlength', charlength).prop('type', 'text').attr('custype', (OPDataType == 'numeric' ? 'number' : 'text'));
                        } else {
                            $('#lblRefNoCharLength').text('');
                            $('#txtSalesPayOtherPaymentTypeCardNo').removeAttr('custype').removeAttr('max').removeAttr('maxlength').prop('type', 'text');
                        }

                        var vouchervalidation;
                        $('#txtSalesPayOtherPaymentTypeCardNo').unbind().keypress(function (e) {
                            var dis = $(this);

                            if (dis.attr('custype') == 'number') {
                                if (dis.val().length >= charlength) {
                                    e.preventDefault()
                                    return;
                                }

                                //if (!NumberDotOnly(dis, e, false)) {
                                //    e.preventDefault();
                                //    return;
                                //}
                            }
                        }).keydown(function () {
                            if ($('#selOtherPaymentType').val() == 'SupercardVoucher') {
                                clearTimeout(vouchervalidation)
                                $('#vouchervalidation').html('<div class="spinner-border spinner-border-sm"></div>')
                                vouchervalidation = setTimeout(function () {
                                    CheckSupercardVoucher($('#txtSalesPayOtherPaymentTypeCardNo').val());
                                }, 3000)
                            }                                                        
                        })
                    });

                    $("#txtSalesPayOtherPaymentTypeAmount").unbind('keydown blur').keydown(function (e) {
                        if (e.keyCode != 110 && e.keyCode != 190) {
                            if (!NumberOnly(e)) return;
                        }
                    }).blur(function () {
                        var pSalesPayCC = parseFloat(CDec2($("#txtSalesPayOtherPaymentTypeAmount").val().replace(/,/g, "")));
                        $("#txtSalesPayOtherPaymentTypeAmount").val((pSalesPayCC > 0 ? AccountingFormat(pSalesPayCC) : ""));
                    });

                    $('#btnGCashPayBal').unbind('click').click(function () {
                        if (IsNumeric($('#lblSalesPayOtherTypeAmountLacking').text())) {
                            $("#txtSalesPayOtherPaymentTypeAmount").val(AccountingFormat(($('#lblSalesPayOtherTypeAmountLacking').text())));
                        } else {
                            $("#txtSalesPayOtherPaymentTypeAmount").val('');
                        }
                    })

                    $('#txtSalesPayOtherPaymentTypeGCashRefNo').unbind('keydown').keydown(function (e) {
                        if(!NumberOnly(e)){
                            return;
                        }
                    })

                    $('#btnSalesPayOtherPaymentTypeSave').unbind('click').click(function (e) {
                        e.preventDefault();
                        var selOtherPaymentType = $('#selOtherPaymentType').val();
                        var inputrefno = $('#txtSalesPayOtherPaymentTypeCardNo');
                        var referenceno = inputrefno.val();
                        var specialchar = referenceno.match(/[!@#$%^&*()_+\-=\[\]{};':"\\|,.<>\/?]/gi) || [];

                        if (selOtherPaymentType != 'Room In' || selOtherPaymentType != 'Send Bill' || selOtherPaymentType != 'GCash' || selOtherPaymentType != 'PayMaya' || selOtherPaymentType != 'GrabFood' || selOtherPaymentType != 'FoodPanda' || selOtherPaymentType != 'AliPay') {
                            if ($.trim($("#selOtherPaymentType").val()) == "") {
                                NewMessageBox("Please select payment type.",
                                   "Payment Type",
                                    [
                                        {
                                            Text: 'Ok'
                                        }
                                    ]
                            );
                                return;
                            }

                            if (($("#txtSalesPayOtherPaymentTypeIssuingOrg").val() == "")
                                && (selOtherPaymentType != 'Complimentary')) {
                                NewMessageBox("Please enter issuing organization.",
                                        "Issuing Organization",
                                        [
                                            {
                                                Text: 'Ok'
                                            }
                                        ]
                                    );

                                return;
                            }

                            if (referenceno == "") {
                                NewMessageBox("Please enter valid card/reference number.",
                                    "Card/Reference Number",
                                    [
                                        {
                                            Text: 'Ok'
                                        }
                                    ]
                                );
                                return;
                            } else {
                                var opt = $('#selOtherPaymentType option:selected');
                                if (CBool(opt.attr('strict')) && referenceno.length < opt.attr('charlength')) {
                                    NewMessageBox('Please enter the ' + opt.attr('charlength') + '-alphanumeric reference number, including the special characters like -,+.', "Card/Reference Number");
                                    return;
                                }

                                if (selOtherPaymentType == 'FoodPanda' && (referenceno.charAt(4) != '-')) {
                                    NewMessageBox('Please enter valid FoodPanda reference number. (e.g. j0un-blz5)')
                                    return;
                                }

                                if (selOtherPaymentType == 'GrabFood' && (referenceno.charAt(2) != '-')) {
                                    NewMessageBox('Please enter valid GrabFood reference number. (e.g. GF-658)')
                                    return;
                                }

                                if (selOtherPaymentType == 'ShareTreats' && !/^\d{1}-\d{2}-\d{3}-\d{3}$/.test(referenceno)) {
                                    NewMessageBox('Please enter valid ShareTreats reference number. (e.g. 1-23-456-789)')
                                    return;
                                }

                                if ((selOtherPaymentType == 'GCash' || selOtherPaymentType == 'PayMaya' || selOtherPaymentType == 'ShopeePay') && specialchar.length > 0) {
                                    NewMessageBox('Please enter valid ' + selOtherPaymentType +' reference number.')
                                    return;
                                }

                                if (inputrefno.attr('custype') == 'number' && !/^[0-9+\-\.\,]+$/.test(referenceno)) {
                                    NewMessageBox('Only numeric and special characters like -, +, and . are allowed to enter.', "Card/Reference Number");
                                }
                            }
                        }

                        if (selOtherPaymentType == 'Room In') {
                            if ($.trim($("#txtSalesPayOtherPaymentTypeRoomNo").val()) == "") {
                                NewMessageBox("Please enter room number.",
                                        "Room No",
                                        [
                                            {
                                                Text: 'Ok'
                                            }
                                        ]
                                    );
                                return;
                            }
                        } else if (selOtherPaymentType == 'GCash') {
                            if ($.trim($('#txtSalesPayOtherPaymentTypeCardNo').val()) == '') {
                                NewMessageBox("Please enter GCash reference number.", "GCash", [{ Text: 'Ok' }]);
                                return;
                            }
                        }

                        if (selOtherPaymentType != 'GoldCard') {
                            if ($.trim($("#txtSalesPayOtherPaymentTypeAmount").val()) == "" || parseFloat(CDec2($.trim($("#txtSalesPayOtherPaymentTypeAmount").val().replace(/,/g, ""))) || '0') == 0) {
                                NewMessageBox("Please enter amount.",
                                   "Amount",
                                    [
                                        {
                                            Text: 'Ok'
                                        }
                                    ]
                            );
                                return;
                            }
                        }

                        if (selOtherPaymentType == 'SupercardVoucher' && !CheckSupercardVoucher(referenceno)) {
                            return
                        }

                        SaveSalesPayOtherType();

                    });

                    $('#btnSalesPayOtherPaymentTypeRemove').unbind('click').click(function (e) {
                        e.preventDefault();

                        NewMessageBox('Remove this record?', 'Remove', [
                            {
                                Text: 'Yes', Click: function(){
                                    RemoveSalesPayOtherType();
                                }
                            }, { Text: 'No' }
                        ])
                    });

                    $('#btnSalesPayOtherPaymentTypeCancel').unbind('click').click(function (e) {
                        e.preventDefault();

                        $(window).scrollTop(0);
                        $('#pageSalesPayment').pageshow();

                    });

                    isInitOtherPaymentFx = true;
                }

                function CheckSupercardVoucher(referenceno) {
                    var svdata = Sql.Execute("SELECT IsActive FROM LibraryVouchers WHERE ReferenceNo = " + ReadyString(referenceno))

                    if (svdata.Rows.length == 0) {
                        $('#txtSalesPayOtherPaymentTypeCardNo').focus();
                        $('#vouchervalidation').html('<div class="text-danger"><span class="bi-x-circle-fill"></span> Invalid</div>')
                        //NewMessageBox('It looks like the voucher serial number has already been used or couldn\'t be found.')
                        return false;
                    } else {
                        if (CBool(svdata.Rows[0].IsActive)) {
                            $('#vouchervalidation').html('<div class="text-success"><span class="bi-check-circle-fill"></span> Valid</div>');
                            return true;
                        } else {
                            $('#txtSalesPayOtherPaymentTypeCardNo').focus();
                            $('#vouchervalidation').html('<div class="text-danger"><span class="bi-exclamation-circle-fill"></span> Claimed</div>');
                            return false;
                        }
                    }
                }

                function getMaxSCDiscountableAmount(){
                    //return CDec2(Business.SystemDefaults.GetSystemDefault("Max SC Discountable Amount"));
                    var pSql = '';

                    pSql = 'Select MaxAllowableDiscountableAmount from LibraryOrganizationTradeName ' +
                            'inner join private.LibraryReceiptSettings on private.LibraryReceiptSettings.OrgTradeNameID = LibraryOrganizationTradeName.ID ' +
                            'inner join private.LibraryReceiptSettingsFowst on private.LibraryReceiptSettingsFowst.ReceiptSettingsID = private.LibraryReceiptSettings.ID ' +                    
                            'where private.LibraryReceiptSettingsFowst.FowstID = ' + ReadyString(sessionStorage.FowstID);

                    return CDec2(Sql.ExecuteScalar(pSql));
                }

                ///////////////////////////////
                function validateIP(string) {
                    var re = /^(\d|[1-9]\d|1\d\d|2([0-4]\d|5[0-5]))\.(\d|[1-9]\d|1\d\d|2([0-4]\d|5[0-5]))\.(\d|[1-9]\d|1\d\d|2([0-4]\d|5[0-5]))\.(\d|[1-9]\d|1\d\d|2([0-4]\d|5[0-5]))$/;

                    return re.test(string);
                }

