                                        { Text: 'Ok',
                                            Click: function () {

                                                //$.mobile.changePage('');

                                                //if (window.location.pathname.toLowerCase() == '/salesmenu/bsposviewall')
                                                //    window.pageHeader.ShowPaymentsPage(false);

                                            }
                                        }
