                                            arSalesPayCustomerName[intSalesPayCustomerNameSurname] = vDataShow.Rows[i].Surname;
                                            arSalesPayCustomerName[intSalesPayCustomerNameFirstName] = vDataShow.Rows[i].FirstName;
                                            arSalesPayCustomerName[intSalesPayCustomerNameMiddleName] = vDataShow.Rows[i].MiddleName;
                                            arSalesPayCustomerName[intSalesPayCustomerNameFullName] = vDataShow.Rows[i].Fullname;
