                function LoadSalesPaymentSRVInfo() {
                    var pData = {};

                    if ($("#txtSalesPaySRVNo").val() == "") {
                        NewMessageBox("Please enter SRV number.",
                                "SRV Number",
                                [
                                    { Text: 'Ok'
                                    }
                                ]
                            );

                        $("#txtSalesPaySRVTransMemoID").val('');
                        $("#txtSalesPaySRVAmount").val('0.00');
                        $("#txtSalesPaySRVConsumedAmount").val('0.00');


                        return;
                    }

                    if ($("#txtSalesPaySRVPinCode").val() == "") {
                        NewMessageBox("Please enter SRV pin code.",
                                "SRV Pin Code",
                                [
                                    { Text: 'Ok'
                                    }
                                ]
                            );

                        $("#txtSalesPaySRVTransMemoID").val('');
                        $("#txtSalesPaySRVAmount").val('0.00');
                        $("#txtSalesPaySRVConsumedAmount").val('0.00');


                        return;
                    }

                    pData.SRVNumber = $("#txtSalesPaySRVNo").val();
                    pData.SRVPin = $("#txtSalesPaySRVPinCode").val();

                    AjaxSend({
                        url: "SalesPayments/getSalesPaymentSRVInfo",
                        data: pData,
                        success: function (vData) {

                            if (vData.MemoID != "") {
                                if ((CDec2(vData.SRVAmount) == 0)
                                    && (CDec2(vData.DestinationPaymentCount) > 0)) {

                                    NewMessageBox('SRV #' + pData.SRVNumber + ' was already consumed.');
                                    return;
                                }
                                $("#txtSalesPaySRVTransMemoID").val(vData.MemoID || '');
                                $("#txtSalesPaySRVAmount").val(AccountingFormat(vData.SRVAmount) || '0.00');

                                if (CDec2($("#lblSalesPaySRVAmountLacking").text()) <= CDec2(vData.SRVAmount)) {
                                    $("#txtSalesPaySRVConsumedAmount").val($("#lblSalesPaySRVAmountLacking").text());
                                } else {
                                    $("#txtSalesPaySRVConsumedAmount").val(AccountingFormat(vData.SRVAmount) || '0.00');
                                }
                                proj.SalesReturnFromOffline = false;
                            } else {
                                OfflineSrv();
                            }

                        },
                        error: function (vError) {
                            OfflineSrv();
                        }
                    });

                    function OfflineSrv() {
                        if (!Business.SystemDefaults.AllowOfflineSrvPayments()) {
                            NewMessageBox("This feature requires internet connection.",
                                "Requires Internet Connection",
                                [
                                    { Text: 'Ok'
                                    }
                                ]
                            );
                            return;
                        }

                        var pResult = Business.TransSalesReturn.GetRemainingValueByPin(pData.SRVNumber, pData.SRVPin);
                        if ((pResult != null)
                            && (pResult.MemoID != "")) {

                            if ((CDec2(pResult.SRVAmount) == 0)
                                && (CDec2(pResult.DestinationPaymentCount) > 0)) {

                                NewMessageBox('SRV #' + pData.SRVNumber + ' was already consumed.');
                                return;
                            }
                            $("#txtSalesPaySRVTransMemoID").val(pResult.MemoID || '');
                            $("#txtSalesPaySRVAmount").val(AccountingFormat(pResult.SRVAmount) || '0.00');

                            if (CDec2($("#lblSalesPaySRVAmountLacking").text()) <= CDec2(pResult.SRVAmount)) {
                                $("#txtSalesPaySRVConsumedAmount").val($("#lblSalesPaySRVAmountLacking").text());
                            } else {
                                $("#txtSalesPaySRVConsumedAmount").val(AccountingFormat(pResult.SRVAmount) || '0.00');
                            }
                            proj.SalesReturnFromOffline = true;
                        } else {

                            $("#txtSalesPaySRVTransMemoID").val('');
                            $("#txtSalesPaySRVAmount").val('0.00');
                            $("#txtSalesPaySRVConsumedAmount").val('0.00');

                            MessageBox("SRV number not found.",
                                "SRV Number",
                                [
                                    { Text: 'Ok'
                                    }
                                ]
                            ); // END MessageBox("SRV number not found.",
                        }
                    } // END function OfflineSrv() {
                }

