                                            var strNetAmountDue = SetPrefixPostfix(AccountingFormat(CDec2(vDataFooter.Rows[0].NetAmountDue) + (isSeniorCitizenPWDDiscount ? 0 : CDec2(vDataFooter.Rows[0].ChargeAmount)) + CDec2(vDataFooter.Rows[0].TipAmount) + CDec2(vDataFooter.Rows[0].LocalTaxAmount)), intFAFCTotalLenght - 22, ' ', 0);

