                function GetSSDItemsWithVatExempt(pInvoiceID) {
                    var pDT;
                    var IsEverythingEligibleForSCD = false;
                    var pSql;
                    var Total = 0;

                    pSql = 'Select DefaultValue from private.SystemDefaults where Description = \'AllItemsEligibleForSCPWDDiscount\'';
                    
                    IsEverythingEligibleForSCD = CBool(Sql.ExecuteScalar(pSql));

                    //pSql = "Select Sum(SubTotal) as Total " +
                    //        " from TransInvoiceItems " +
                    //        " inner join LibraryOrganizationPIM " +
                    //        " ON LibraryOrganizationPIM.ProductID = TransInvoiceItems.ProductID " +
                    //        " where InvoiceID = " + ReadyString(pInvoiceID)

                    pSql = "Select TransInvoiceItems.ID as ID, TransInvoiceItems.ProductID, SubTotal as Total, MaxAllowableDiscountableAmount*TransInvoiceItems.Quantity as MaxAllowableDiscountableAmount, DiscountedPriceAction, ItemBasedMaxAllowableDiscount " +
                            " from TransInvoiceItems " +
                            " inner join LibraryOrganizationPIM " +
                            " ON LibraryOrganizationPIM.ProductID = TransInvoiceItems.ProductID " +
                            " where InvoiceID = " + ReadyString(pInvoiceID)

                    if(!IsEverythingEligibleForSCD)
                        pSql += " AND LibraryOrganizationPIM.IsVatExempt=1";

                    pDT = Sql.Execute(pSql);

                    //check item based max discountable amount
                    var ItemBasedMaxAllowableDiscount;

                    ItemBasedMaxAllowableDiscount = CStr2(pDT.Rows[0].ItemBasedMaxAllowableDiscount);

                    if (ItemBasedMaxAllowableDiscount.length > 0) {
                        //get item price based on store price level
                        //var pPriceLevelID = Sql.ExecuteScalar('Select DefaultSellingPriceLevel from LibraryOrganizationFranchisee where FranchiseeOrgFowstID=' + ReadyString(sessionStorage.FowstID) + ' LIMIT 1')
                        var pPriceLevelID = Sql.ExecuteScalar("Select DefaultSellingPriceLevel from LibraryOrganizationFranchisee where FranchiseeOrgFowstID=" + ReadyString(sessionStorage.FowstID) + " AND OwnershipType = 'Company-Owned' LIMIT 1")

                        if (CStr2(pPriceLevelID).length > 0) {
                            Total = CDec2(Business.LibraryPIMProduct.GetPrice(ItemBasedMaxAllowableDiscount, '', pPriceLevelID, Web.OrgID()));

                        }
                    } else {
                        for (var i = 0; i <= pDT.Rows.length - 1; i++) {

                            //if (pDT.Rows[i].MaxAllowableDiscountableAmount == undefined) {
                            //    Total += pDT.Rows[i].Total;
                            //} else if (CInt2(pDT.Rows[i].MaxAllowableDiscountableAmount) == 0) {

                            //}
                            Total += CDec2(pDT.Rows[i].MaxAllowableDiscountableAmount && CInt2(pDT.Rows[i].MaxAllowableDiscountableAmount) > 0 ? pDT.Rows[i].MaxAllowableDiscountableAmount : pDT.Rows[i].Total)

                            //if (CInt2(pDT.Rows[i].MaxAllowableDiscountableAmount) > 0) {
                            //    Total += GetTotalOfItemModifiers(pDT.Rows[i].ID);
                            //}

                            DiscountedPriceAction = CStr2(pDT.Rows[i].DiscountedPriceAction);
                        }
                    }

                    return Total;
                    //return pDT.Rows[0].Total;
                }

                function GetTotalOfItemModifiers(ID) {
                    var pSql = 'Select SUM(Subtotal) from TransInvoiceItemsModifier where InvoiceItemID = ' + ReadyString(ID)

                    return CDec2(Sql.ExecuteScalar(pSql));
                }

                function GetInvoiceCharges(pInvoiceID) {
                    pSql = "Select SUM(ChargeAmount) from TransInvoiceCharges where InvoiceID=" + ReadyString(pInvoiceID);

                    return CDec2(Sql.ExecuteScalar(pSql));
                }

